import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long cap = Long.parseLong(next());
        String[][] ops = new String[(int) n][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        Map<Long, Long> cache = new LinkedHashMap<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long key = Long.parseLong(ops[i][1]);
            if (ops[i][0].equals("get")) {
                Long value = cache.remove(key);
                if (value == null) {
                    sb.append(-1).append("\n");
                } else {
                    cache.put(key, value);
                    sb.append(value).append("\n");
                }
            } else {
                if (cache.containsKey(key)) {
                    cache.remove(key);
                } else if (cache.size() == cap) {
                    cache.remove(cache.keySet().iterator().next());
                }
                cache.put(key, Long.parseLong(ops[i][2]));
            }
        }
        System.out.print(sb);
    }
}
